gold.schema_ddl:
CREATE TYPE condizione_movimento AS ENUM ('pianificato', 'in_corso', 'completato', 'annullato');

CREATE TABLE ordini (
    id SERIAL PRIMARY KEY,
    data_ordine DATE NOT NULL,
    cliente TEXT NOT NULL
);

CREATE TABLE movimenti_trasporto (
    id SERIAL PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini(id),
    condizione_attuale condizione_movimento NOT NULL,
    data_movimento TIMESTAMP NOT NULL DEFAULT NOW(),
    indirizzo_destinazione TEXT NOT NULL,
    peso_kg NUMERIC(8,2) CHECK (peso_kg > 0)
);
